INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7198104, 1107188, 61396, '<td valign="top">too funny!</td>', 'too funny!', '2014-04-03 13:55:32.000000', NULL, 1),
(7198106, 1106920, 100831, '<td valign="top">.. nature is among us. and there''s lots to marvel in this image.</td>', '.. nature is among us. and there''s lots to marvel in this image.', '2014-04-03 13:57:10.000000', NULL, 1),
(7198107, 1107186, 61396, '<td valign="top">nicely captured</td>', 'nicely captured', '2014-04-03 13:57:39.000000', NULL, 1),
(7198109, 1107172, 100831, '<td valign="top">I''m having trouble putting my thoughts into words but I love this... the processing, composition and colors are so well thought out... turns what could be a complete mess of a picture into a beauty.</td>', 'I''m having trouble putting my thoughts into words but I love this... the processing, composition and colors are so well thought out... turns what could be a complete mess of a picture into a beauty.', '2014-04-03 14:06:11.000000', NULL, 1),
(7198110, 1107104, 100831, '<td valign="top">great idea - I like the dichotomy.</td>', 'great idea - I like the dichotomy.', '2014-04-03 14:07:11.000000', NULL, 1),
(7198124, 1107165, 173844, '<td valign="top">Great idea, execution, perspective, mood and details.  My favorite in the challenge.  One quibble --  the flaming eye lends a busyness to the upper left area; maybe smaller, if that wouldn''t be untrue to the books.</td>', 'Great idea, execution, perspective, mood and details.  My favorite in the challenge.  One quibble --  the flaming eye lends a busyness to the upper left area; maybe smaller, if that wouldn''t be untrue to the books.', '2014-04-03 15:30:01.000000', NULL, 1),
(7198125, 1106729, 173844, '<td valign="top">The real pathos here is handled a bit flippantly, but the photo is terrific.  The color tone is suitably somber with regard to both the mood and the terrain.  The power lines are particularly apposite, echoing the cross in shape and, analogous to snares, hinting at a host of tragedies.</td>', 'The real pathos here is handled a bit flippantly, but the photo is terrific.  The color tone is suitably somber with regard to both the mood and the terrain.  The power lines are particularly apposite, echoing the cross in shape and, analogous to snares, hinting at a host of tragedies.', '2014-04-03 15:39:21.000000', NULL, 1),
(7198127, 1107147, 173844, '<td valign="top">Really funny.  Great expression.  Yet there''s the feel of a religious parable here, too --  simple and emotive.  And it''s beautifully handled.  It also reminds me of a diorama. Quite successful.</td>', 'Really funny.  Great expression.  Yet there''s the feel of a religious parable here, too --  simple and emotive.  And it''s beautifully handled.  It also reminds me of a diorama. Quite successful.', '2014-04-03 15:46:51.000000', NULL, 1),
(7198128, 1107190, 173844, '<td valign="top">Very creative and well done.  Fine pose and expression.  The cat is a great touch.  The colors make a modest harmony.</td>', 'Very creative and well done.  Fine pose and expression.  The cat is a great touch.  The colors make a modest harmony.', '2014-04-03 15:54:40.000000', NULL, 1),
(7198131, 1107100, 173844, '<td valign="top">I like the close crop on the cowboy here, and his expression which could originate from any number of emotions.  I also like the artistic background treatment.</td>', 'I like the close crop on the cowboy here, and his expression which could originate from any number of emotions.  I also like the artistic background treatment.', '2014-04-03 15:59:05.000000', NULL, 1),
(7198135, 1107015, 173844, '<td valign="top">Exquisite scene and model, completely believable as a fairy tale.  The door, though, to me, is confusing.</td>', 'Exquisite scene and model, completely believable as a fairy tale.  The door, though, to me, is confusing.', '2014-04-03 16:05:47.000000', NULL, 1),
(7198139, 1107101, 173844, '<td valign="top">Wild! Is this real or am I just naive?  In any case, it''s a startling image that quite suits the challenge.  Well done.</td>', 'Wild! Is this real or am I just naive?  In any case, it''s a startling image that quite suits the challenge.  Well done.', '2014-04-03 16:09:18.000000', NULL, 1),
(7198142, 1107188, 173844, '<td valign="top">Warm and plaintive both.  It hurts to be spurned.</td>', 'Warm and plaintive both.  It hurts to be spurned.', '2014-04-03 16:11:00.000000', NULL, 1),
